INSERT INTO predefined_messages (category_id, message_text, sort_order) VALUES
('cumpleanos', 'Hola, es súper importante que sepas que este nuevo año te abrazara con alegrías, salud y sueños cumplidos por toneladas. ¡Feliz cumpleaños!', 1),
('cumpleanos', 'Un día como hoy, el mundo recibió un regalo en forma de tu existencia y nosotros felices de poder tenerte cerca y compartir siempre contigo. Que tengas un día lleno de amor y luz.', 2),
('cumpleanos', 'Que cada velita encendida hoy represente una razón más para sonreír, para que tengas a la mano todas las herramientas que sean requeridas para que cumplas todos tus sueños y deseos. ¡Felicidades!', 3),
('cumpleanos', '¡Feliz vuelta al sol! Que cada instante de este nuevo ciclo en tu vida esté lleno de grandes propósitos cumplidos y miles de alegrías.', 4),
('cumpleanos', 'Tu presencia, tu sonrisa, tu forma de ser, hace especial el mundo que te rodea. Gracias por existir. ¡Feliz cumpleaños!', 5),
('cumpleanos', 'Hoy celebramos tu nacimiento, tu vida, tu historia y todo lo que estás por conquistar. ¡Brindo por ti, por tus sueños y tu futuro!', 6),
('cumpleanos', 'Que este cumpleaños te traiga nuevas pasiones, nuevos caminos y muchos logros, abrazos sinceros y momentos inolvidables.', 7),
('cumpleanos', 'Que el amor siempre te encuentre en cada rincón de donde quiera que te encuentres de este día tan especial. ¡Feliz cumpleaños.', 8),
('cumpleanos', 'Tu luz es gran inspiración para quienes te rodean. Te deseamos que sigas brillando siempre y cumplas todos tus sueños. ¡Feliz cumpleaños.', 9),
('cumpleanos', 'Para ti hoy un nuevo año comienza, una nueva oportunidad para soñar, sentir, para amor y crecer. ¡Felicidades!', 10),
('cumpleanos', 'Que la vida te sorprenda siempre con regalos que no se envuelven, pero se sienten y valen más que el oro y se atesoran en el corazón. ¡Feliz cumpleaños!', 11),
('cumpleanos', 'En tu día, celebro tu existencia con alegría, recuerdos hermosos, respeto y muchísimo cariño. ¡Disfruta tu día al máximo!', 12),
('cumpleanos', 'Gracias por ser parte de mi historia por acompañarme en mi camino. Hoy, deseo que el universo te regale paz y plenitud. ¡Feliz cumpleaños!', 13),
('cumpleanos', 'Cada cumpleaños es un recordatorio de lo valioso y especial que eres en nuestras vidas. Que este sea inolvidable', 14),
('cumpleanos', 'Tu presencia y energía transforma cada momento. Hoy celebramos tu nacimiento y deseamos grandes éxitos. ¡Feliz cumpleaños!', 15),
('cumpleanos', 'Que tu nuevo año esté bordado de risas, aprendizajes, alegrías y sueños cumplidos. ¡Felicidades!', 16),
('cumpleanos', 'Las estrellas brillan hoy especialmente para ti, te recargan de energía para que seas feliz. ¡Feliz cumpleaños!', 17),
('cumpleanos', 'Tú eres un gran regalo que no necesita envoltura. Que este día sea tan especial como tú y estés rodeado de todos tus seres amados. ¡Felicidades!', 18),
('cumpleanos', 'Que el calendario hoy en tu día te regale más momentos dulces que días amargos, más aciertos que desaciertos y muchas alegrías ¡Felices nuevos comienzos!', 19),
('cumpleanos', 'Un abrazo desde el corazón para quien merece siempre lo mejor, que hoy en tu día todos tus sueños se cumplan ¡Feliz cumpleaños!', 20);
INSERT INTO predefined_messages (category_id, message_text, sort_order) VALUES
('graduacion', 'Hoy con tu grado cierras un capítulo increíble y nos sentimos felices de compartir este momento contigo, a partir de mañana comienzas un capítulo aún mejor y un gran camino para tu vida. ¡Felicidades por tu logro!', 1),
('graduacion', 'Tu esfuerzo florece e inicia a dar frutos a partir de este momento. Te deseamos que lo que viene sea aún más brillante para ti. ¡Enhorabuena!', 2),
('graduacion', 'Cada trasnocho, cada paso que diste te trajo hoy aquí a celebrar. Que nunca se apaguen tus ganas de aprender. ¡Felicidades!', 3),
('graduacion', 'Graduarte no solo es terminar algo: es demostrar de lo que estás hecho y de lo mucho que eres capaz, hoy nos sentimos orgullosos de ti. ¡Felicidades por tu logro!', 4),
('graduacion', 'Que la emoción y la alegría de este día te recuerde que todo lo que soñaste es posible. Continúa soñando y materializa cada uno de ellos ¡Felicidades!', 5),
('graduacion', '¡Felicidades! Hoy celebramos tu constancia, tu disciplina, tu dedicación, tu luz y te acompañamos a recibir la recompensa. ¡Felicidades por tu grado!', 6),
('graduacion', 'Este logro es tuyo y de todos los que te apoyaron en el camino, familiares y amigos. ¡Felicidades por este gran logro!', 7),
('graduacion', 'Con tu grado dejas hermosas huella y abres grandes caminos. El futuro será tu lienzo. ¡A pintarlo con pasión!', 8),
('graduacion', 'Tu diploma es el símbolo de tu grado y de tu dedicación, pero tu crecimiento es el verdadero premio. ¡Adelante y muchas felicidades!', 9),
('graduacion', 'Todo lo que aprendiste durante tu carrera ya vive en ti. Ahora úsalo para cambiar y mejorar el mundo. ¡Felicidades por tu logro!', 10),
('graduacion', 'Tu esfuerzo merece cada aplauso, cada palabra de admiración y cada buen deseo de éxito. ¡Disfruta esta victoria al máximo, Felicidades!', 11),
('graduacion', 'La vida siempre te espera con nuevos retos. Pero hoy, solo déjate abrazar por tu logro y el amor de las personas que te rodean. ¡Feliz graduación!', 12),
('graduacion', 'Tu historia se escribe con valentía y determinación. Hoy celebramos un capítulo épico y materialización del camino que recorres. ¡Felicidades por tu logro!', 13),
('graduacion', 'Tu grado más que una meta alcanzada, es un nuevo camino que se abre a grandes éxitos. ¡Qué bello verte crecer. Felicidades!', 14),
('graduacion', 'El mundo necesita tu talento, tu personalidad, tu humanidad. Este título es solo el comienzo. ¡Ve con todo. Felicidades por tu grado!', 15),
('graduacion', 'Hoy es el reflejo de todo lo que superaste y de todo lo que puedes lograr. ¡Felicitaciones y nunca olvides lo capaz que eres!', 16),
('graduacion', 'Lo hiciste. Con lágrimas, risas y mucho café. Y aquí estás, brillando y cumpliendo a tus logros y sueños. ¡Felicidades por tu logro!', 17),
('graduacion', 'Que cada logro futuro te recuerde lo que celebramos hoy y cumplas con la promesa de ser un buen profesional mejorar con tu profesión el mundo. ¡Felicitaciones!', 18),
('graduacion', 'Tu éxito inspira y motiva. Gracias por mostrar que los sueños, con esfuerzo y disciplina, sí se cumplen. ¡Felicidades por tu logro!', 19),
('graduacion', 'Alza la mirada al horizonte y disfruta lo que ves, respira hondo y sonríe. Has llegado… y apenas comienzas. ¡Felicidades por tu logro!', 20);
INSERT INTO predefined_messages (category_id, message_text, sort_order) VALUES
('aniversario', 'Cada día contigo es un regalo, una bendición, pero hoy celebramos el más valioso de todos: nuestro amor y compromiso de vida. Feliz aniversario.', 1),
('aniversario', 'El tiempo pasa muy rápido, pero lo que siento por ti solo crece aún más y más. Gracias por compartir y estar en este viaje conmigo. Feliz aniversario.', 2),
('aniversario', 'Un aniversario más para recordarte que sigues siendo mi persona favorita contemplada y amada, un aniversario más y yo te deseo cada día más. Feliz aniversario.', 3),
('aniversario', 'Tu compañía durante todo este tiempo juntos, sigue siendo mi refugio, mi alegría y mi fortaleza, me llenas de motivos para luchar cada día y amarte cada vez más ¡Feliz aniversario!', 4),
('aniversario', 'Amar y ser amado por ti ha sido mi mayor aventura llena de emociones. Solo deseo que vengan muchos años más de esas hermosas aventuras que atesoraré toda mi vida.', 5),
('aniversario', 'Hoy celebramos lo que hemos decidido construir: amor, confianza, compromiso y memorias eternas. Feliz aniversario.', 6),
('aniversario', 'Cada aniversario es un recordatorio de lo afortunado/a que soy por tenerte.', 7),
('aniversario', 'Nuestro amor no necesita palabras… pero hoy quiero decirte que es lo más bello que tengo.', 8),
('aniversario', 'Entre abrazos y silencios, nuestro vínculo se hace cada vez más fuerte. ¡Feliz aniversario!', 9),
('aniversario', 'Gracias por caminar a mi lado con ternura y convicción. Brindo por todo lo que aún nos espera.', 10),
('aniversario', 'Nuestro amor no se mide en años, sino en momentos compartidos. Gracias por tantos instantes inolvidables.', 11),
('aniversario', 'Qué bonito es mirar atrás y ver que siempre hemos estado del mismo lado.', 12),
('aniversario', 'Este aniversario me recuerda cuánta magia hay en lo cotidiano contigo.', 13),
('aniversario', 'No importa cuántas veces celebre este día… cada vez me emociona como la primera.', 14),
('aniversario', 'Nuestra historia merece celebrarse en voz alta. ¡Felicidades por este amor que crece!', 15),
('aniversario', 'Tu amor es mi hogar. Hoy celebramos que seguimos construyéndolo juntos.', 16),
('aniversario', 'Nuestro vínculo está tejido de paciencia, cariño y aventuras compartidas. ¡Feliz aniversario!', 17),
('aniversario', 'Hoy celebro que existimos, que resistimos, y que seguimos eligiéndonos cada día.', 18),
('aniversario', 'Este aniversario es prueba de que lo verdadero perdura y se fortalece.', 19),
('aniversario', 'Gracias por cada mirada cómplice, por cada paso compartido. ¡Por muchos más aniversarios!', 20);
INSERT INTO predefined_messages (category_id, message_text, sort_order) VALUES
('luto', 'Acompaño tu dolor con respeto y silencio. Que encuentres consuelo en los recuerdos compartidos.', 1),
('luto', 'No hay palabras suficientes, solo un corazón que se une al tuyo en este momento difícil.', 2),
('luto', 'Que la paz te abrace mientras honras la memoria de quien tanto significó.', 3),
('luto', 'Su luz sigue viva en cada gesto, en cada recuerdo. Un abrazo sincero en tu duelo.', 4),
('luto', 'Que el amor que rodea tu pérdida te sostenga en los días más nublados.', 5),
('luto', 'Aunque no esté físicamente, su esencia vive en quienes lo amaron.', 6),
('luto', 'Que cada lágrima que brota sea también un homenaje al amor que no se olvida.', 7),
('luto', 'Te acompaño con todo mi respeto. Que el tiempo sane sin borrar lo vivido.', 8),
('luto', 'Su partida deja un silencio profundo, pero también un legado de amor.', 9),
('luto', 'El duelo es la forma más sincera en que el amor se manifiesta cuando perdemos.', 10),
('luto', 'A veces el corazón necesita espacio para simplemente sentir. Aquí estoy contigo.', 11),
('luto', 'Que encuentres fortaleza en los gestos de quienes te rodean con cariño.', 12),
('luto', 'Recordar a quien partió es la manera más bonita de seguir amándolo.', 13),
('luto', 'Nada ni nadie podrá quitarte lo compartido. Ese vínculo permanece eterno.', 14),
('luto', 'Tu dolor merece ser escuchado y abrazado. Mi pensamiento está contigo.', 15),
('luto', 'El alma que se va deja huellas que el tiempo no borra.', 16),
('luto', 'La ausencia duele, pero también revela cuán profundo fue el vínculo.', 17),
('luto', 'En medio del duelo, que el amor recibido te sostenga.', 18),
('luto', 'Que el recuerdo se vuelva luz. Que el dolor se vuelva pausa. Que la vida continúe con cariño.', 19),
('luto', 'Tu pérdida es compartida desde lo más humano. Aquí estoy, contigo, en silencio y solidaridad.', 20);
INSERT INTO predefined_messages (category_id, message_text, sort_order) VALUES
('amor', 'Amarte es descubrir un mundo nuevo en cada mirada tuya.', 1),
('amor', 'Tu presencia hace que todo lo cotidiano se vuelva extraordinario.', 2),
('amor', 'El amor contigo no tiene horarios, solo instantes eternos.', 3),
('amor', 'Tu voz es el lugar donde mi corazón siempre quiere volver.', 4),
('amor', 'No sé si existe el destino, pero contigo cada coincidencia se siente perfecta.', 5),
('amor', 'Te pienso y todo se pinta de colores cálidos y sinceros.', 6),
('amor', 'Lo más bonito que me pasó... fue cruzarme contigo.', 7),
('amor', 'Estás en mi mente, mi piel, y en cada suspiro que no sé cómo explicar.', 8),
('amor', 'Contigo el tiempo no corre, se queda contemplando.', 9),
('amor', 'Eres el mensaje que mi alma siempre quiso leer.', 10),
('amor', 'No quiero promesas, solo seguir escribiendo contigo cada capítulo.', 11),
('amor', 'Amarte es fácil, pero entender todo lo que siento es otra historia.', 12),
('amor', 'Hay abrazos que curan. El tuyo es uno de ellos.', 13),
('amor', 'Eres hogar, aunque no estemos en el mismo lugar.', 14),
('amor', 'Tu amor me hizo entender que lo verdadero no se grita, se siente.', 15),
('amor', 'No necesito mil palabras cuando con una mirada me lo dices todo.', 16),
('amor', 'A veces, el mejor plan es simplemente estar juntos sin hacer nada.', 17),
('amor', 'Entre todos los caminos, el tuyo siempre será mi favorito.', 18),
('amor', 'Gracias por ser tú. Así, sin filtros.', 19),
('amor', 'Si pudiera enredarme en tus pensamientos, me quedaría a vivir ahí.', 20);